# DK ALK.  Aabenraa Amtsb - Løgumkloster Amtsb
with detail = 2 {
    let ah = path("d2.dk.alk.1");
    let hl = path("d2.dk.alk.2");

    with railway = :third :narrow:g1000 :pax :removed {
        with link = "line.dk.ALK" {
            track(
                    ah[:aba, :hov.xa - 0.5md]
                ..  ah[:hov.ya, :hov.ya + 0.1dl] >> 0.5md << 0.5lt
            );
            line_label(:right:w, ah[:aba + 10.5km] >> 0.5lt,
                (0dt, -0.3dt), "ALK"
            );
        }

        # point.dk.Hovslund  dk.FPB

        with link = "line.dk.ALK" {
            track(
                    hl[:hov.yl - 0.1dl, :hov.yl] >> 0.5md << 0.5lt
                ..  hl[:hov.xl + 0.5md, :hov.xl + 3.51km]
            );
            line_label(:right:e, hl[:hov.xl + 3.5km] >> 0.5lt, "ALK");
            track(hl[:hov.xl + 3.49km, :hel.yv]);
            # dk.RBB
            track(hl[:bea.yv, :bea.yv + 1.51km]);
            line_label(:right:s, hl[:bea.yv + 1.5km] >> 0.5lt,
                (0.2dt, 0dt), "ALK"
            );
            track(hl[:bea.yv + 1.49km, :sgr.yo]);
            track(hl[:sgr.yv, :ass.yv]);
            track(hl[:log.yo, :log]);
        }
    }
}


